window.blogDetail = {"blogId":1529618198,"blogType":0,"pubTime":"2018-06-22 05:56","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"诗到沧桑句便工——“诗圣”杜甫","commentNum":0,"effect1":1025,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"“不懂杜甫，就不懂人世沧桑”，只有读懂沧海桑田，才能进入杜甫的世界，才能进入这个为整部唐诗添上一抹厚重底色的“诗圣”的内心。<br/>我们对于杜甫的印象，停留在那一串光冕堂皇的名号上，“诗圣”，“诗史”，“现实主义大诗人”“沉郁顿挫之先驱”，这一个个看似光彩夺目，流芳千古美名，掩盖了杜甫背后的沧桑，也掩盖了杜甫作为一个颠沛流离的流亡者的困苦和不堪，教科书上那些或沉郁顿挫或慷慨激昂的文字，对于未了解...","img":[{"url":"https://a1.qpic.cn/psb?/V115Q4qb1YRbBN/LpKgnNWo*iSEZn0Rq5JlGAit*kfcfwucbyVz3f0eaG8!/c/dOAAAAAAAAAA&ek=1&kp=1&pt=0&bo=gAIEAgAAAAAREKM!&tl=1&su=014263457&tm=1779170400&dis_t=1779172628&dis_k=c1e58ae7f7a60a2dcc14308e4104bfef&sce=0-12-12&rf=0-2-8","custom_url":"images/CCF5B0F7.jpeg"},{"url":"https://a1.qpic.cn/psb?/V115Q4qb1YRbBN/HeIrIL1RDg6lN5ItOGt5qnyRrA6ce8nSSPEZOUUfar0!/c/dPQAAAAAAAAA&ek=1&kp=1&pt=0&bo=SgG3AQAAAAARENo!&tl=1&su=014865025&tm=1779170400&dis_t=1779172628&dis_k=56a261844047ff123beb93ec2cb0e5d1&sce=0-12-12&rf=0-2-8","custom_url":"images/1C485783.jpeg"}],"artype":1,"arUins":"","blogid":1529618198,"voteids":0,"pubtime":1529618198,"replynum":0,"category":"个人日记","effect":1025,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1529618198,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"诗到沧桑句便工——“诗圣”杜甫","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1529618198"}